import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.SG7_9Yi6.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"peregrin","text":"Orchestrate your agents","tagline":"Event-driven orchestration for agent workflows — nodes, campaigns, and remote transport across your machines.","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Architecture","link":"/explanation/architecture"}]},"features":[{"title":"Nodes","details":"A daemon per machine hosts the session plane (via sepia serve) and campaign drivers — one install, two capability planes."},{"title":"Campaigns","details":"Declarative workflows over agents — graph-walking engine, YAML loader, templating, durable runs."},{"title":"Hub","details":"Aggregation across nodes — merged entity/session views, sync, lock arbitration, and fleet dispatch."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function s(o,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Peregrin is event-driven orchestration for agent workflows: a daemon per machine (<code>peregrin-node</code>) hosts the session plane and campaign engines, a headless <code>peregrin-hub</code> aggregates nodes into one fleet view, and declarative YAML campaigns turn events (webhook pushes, schedules, CI verdicts) into bounded agent work.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Coding agents multiply fast; the hard part is deciding <em>who may act on a session, when, and on which machine</em>. Peregrin is the policy layer — sepia does things <em>to</em> sessions, peregrin decides <em>who/when/where</em> — with durable, queue-superseded runs and an explicit capabilities/secret boundary so AI-governed workflows stay safe.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> the session/entity planes&#39; integration side, campaigns, drivers, events, remote transport, the hub gateway.</li><li><strong>Doesn&#39;t own:</strong> session mechanism (<a href="https://9aia.com/sepia/" target="_blank" rel="noreferrer">sepia</a>), the generic entity substrate (<a href="https://github.com/9aia/hypha" target="_blank" rel="noreferrer">hypha</a>), bundle distribution and service lifecycle (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Learn by doing — first node, first campaign</td><td><a href="/peregrin/tutorials/getting-started.html">Tutorials</a></td></tr><tr><td>Do a specific task (run a node, serve campaigns, deploy a bundle)</td><td><a href="/peregrin/how-to/">How-to</a></td></tr><tr><td>Understand the design (planes, drivers, safety, threat model)</td><td><a href="/peregrin/explanation/">Explanation</a></td></tr><tr><td>Look up a verb, env var, or schema field</td><td><a href="/peregrin/reference/">Reference</a></td></tr></tbody></table>',8)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
